 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # Non-background markers on the horizontal 1-band project upward.
    # Color 2 makes a four-cell column; color 8 makes a three-cell column.
    heights = {2: 4, 8: 3}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            height = heights.get(value)
            if height is not None:
                top = r - height
                if top >= 0:
                    out[top][c] = value
                    for rr in range(top + 1, r):
                        out[rr][c] = 1
    return out
